class Solution {
    int memo[1 << 15];
public:
    int minStickers(vector<string>& stickers, string target) {
        int n = target.size();
        memset(memo, -1, sizeof(memo));
        memo[(1 << n) - 1] = 0;
        int m = stickers.size();
        vector<vector<int>> counts(m, vector<int>(26, 0));
        for (int i = 0; i < m; ++i) {
            for (char c : stickers[i]) counts[i][c - 'a']++;
        }
        auto dfs = [&](auto& self, int mask) -> int {
            if (memo[mask] != -1) return memo[mask];
            int first = -1;
            for (int i = 0; i < n; ++i) {
                if (!(mask & (1 << i))) {
                    first = i;
                    break;
                }
            }
            if (first == -1) return 0;
            int ans = 1e9;
            for (int j = 0; j < m; ++j) {
                if (counts[j][target[first] - 'a'] == 0) continue;
                int next_mask = mask;
                vector<int> rem = counts[j];
                for (int i = 0; i < n; ++i) {
                    if (!(next_mask & (1 << i)) && rem[target[i] - 'a'] > 0) {
                        rem[target[i] - 'a']--;
                        next_mask |= (1 << i);
                    }
                }
                ans = min(ans, 1 + self(self, next_mask));
            }
            return memo[mask] = ans;
        };
        int res = dfs(dfs, 0);
        return res >= 1e9 ? -1 : res;
    }
};

class Solution {
    private int[] memo;
    public int minStickers(String[] stickers, String target) {
        int n = target.length();
        int m = stickers.length;
        memo = new int[1 << n];
        Arrays.fill(memo, -1);
        memo[(1 << n) - 1] = 0;
        int[][] counts = new int[m][26];
        for (int i = 0; i < m; ++i) {
            for (char c : stickers[i].toCharArray()) counts[i][c - 'a']++;
        }
        int res = dfs(0, target, stickers, counts);
        return res >= 1000000 ? -1 : res;
    }
    private int dfs(int mask, String target, String[] stickers, int[][] counts) {
        if (memo[mask] != -1) return memo[mask];
        int n = target.length();
        int first = -1;
        for (int i = 0; i < n; ++i) {
            if ((mask & (1 << i)) == 0) {
                first = i;
                break;
            }
        }
        if (first == -1) return 0;
        int ans = 1000000;
        for (int j = 0; j < stickers.length; ++j) {
            if (counts[j][target.charAt(first) - 'a'] == 0) continue;
            int nextMask = mask;
            int[] rem = counts[j].clone();
            for (int i = 0; i < n; ++i) {
                if ((nextMask & (1 << i)) == 0 && rem[target.charAt(i) - 'a'] > 0) {
                    rem[target.charAt(i) - 'a']--;
                    nextMask |= (1 << i);
                }
            }
            ans = Math.min(ans, 1 + dfs(nextMask, target, stickers, counts));
        }
        return memo[mask] = ans;
    }
}

var minStickers = function(stickers, target) {
    const n = target.length;
    const memo = new Int32Array(1 << n).fill(-1);
    memo[(1 << n) - 1] = 0;
    const counts = stickers.map(s => {
        const arr = new Int32Array(26);
        for (let i = 0; i < s.length; ++i) arr[s.charCodeAt(i) - 97]++;
        return arr;
    });
    function dfs(mask) {
        if (memo[mask] !== -1) return memo[mask];
        let first = -1;
        for (let i = 0; i < n; ++i) {
            if (!(mask & (1 << i))) {
                first = i;
                break;
            }
        }
        if (first === -1) return 0;
        let ans = 1e9;
        const targetChar = target.charCodeAt(first) - 97;
        for (let j = 0; j < stickers.length; ++j) {
            if (counts[j][targetChar] === 0) continue;
            let nextMask = mask;
            const rem = new Int32Array(counts[j]);
            for (let i = 0; i < n; ++i) {
                const c = target.charCodeAt(i) - 97;
                if (!(nextMask & (1 << i)) && rem[c] > 0) {
                    rem[c]--;
                    nextMask |= (1 << i);
                }
            }
            ans = Math.min(ans, 1 + dfs(nextMask));
        }
        return memo[mask] = ans;
    }
    const res = dfs(0);
    return res >= 1e9 ? -1 : res;
};
